1	import { Router, type IRouter } from "express";
2	import { and, eq, ne, sql } from "drizzle-orm";
3	import {
4	  db,
5	  bookingsTable,
6	  courtsTable,
7	  userProfilesTable,
8	  facilitiesTable,
9	  gamesTable,
10	  coachesTable,
11	  courtCoachesTable,
12	} from "@workspace/db";
13	import {
14	  CreateCheckoutSessionBody,
15	  CreateCheckoutSessionResponse,
16	  ConfirmPaymentBody,
17	  ConfirmPaymentResponse,
18	} from "@workspace/api-zod";
19	import { logger } from "../lib/logger";
20	import { sendBookingConfirmationEmail, sendOwnerBookingNotificationEmail } from "../lib/email";
21	import { getUncachableStripeClient, getStripePublishableKey } from "../stripeClient";
22	import { getCurrentUserId, requireAuth, getUserRole } from "../lib/auth";
23	import { timingSafeEqualToken } from "../lib/guestToken";
24	import { getCoachAvailability, vilniusToUtc } from "../lib/coach-availability";
25	import { maybeIssueCoachTransfer } from "../lib/coach-transfer";
26	
27	const COURT_PLATFORM_FEE_PCT = 5;
28	const SLOT_MS = 30 * 60_000;
29	
30	/**
31	 * Re-authorize a coach attachment at checkout time and compute the coach's
32	 * share in integer cents. Returns either a valid attachment or an error
33	 * code suitable for a 422 response. Mirrors the filters used by
34	 * GET /courts/:id/available-coaches so a player can't bypass the picker.
35	 */
36	async function authorizeAndPriceCoach(args: {
37	  coachId: number;
38	  courtId: number;
39	  date: string;     // YYYY-MM-DD (Europe/Vilnius)
40	  startTime: string; // HH:MM
41	  endTime: string;   // HH:MM
42	}): Promise<
43	  | { ok: true; coachUserId: string; coachCents: number }
44	  | { ok: false; error: string }
45	> {
46	  const [coach] = await db
47	    .select({
48	      id: coachesTable.id,
49	      userId: coachesTable.userId,
50	      pricePerHour: coachesTable.pricePerHour,
51	      status: coachesTable.status,
52	      isAcceptingStudents: coachesTable.isAcceptingStudents,
53	      courtPaymentModel: coachesTable.courtPaymentModel,
54	      travelPolicy: coachesTable.travelPolicy,
55	    })
56	    .from(coachesTable)
57	    .where(eq(coachesTable.id, args.coachId));
58	
59	  if (!coach) return { ok: false, error: "Coach not found" };
60	  if (coach.status !== "approved") return { ok: false, error: "Coach not approved" };
61	  if (!coach.isAcceptingStudents) return { ok: false, error: "Coach not accepting students" };
62	  if (coach.courtPaymentModel !== "student_pays_court") {
63	    return { ok: false, error: "Coach payment model unsupported" };
64	  }
65	  if (coach.pricePerHour == null || coach.pricePerHour <= 0) {
66	    return { ok: false, error: "Coach price unset" };
67	  }
68	
69	  // Coach Stripe Connect must be live — otherwise we can't transfer them
70	  // their share and the booking would silently strand funds on platform.
71	  const [profile] = await db
72	    .select({ status: userProfilesTable.stripeAccountStatus })
73	    .from(userProfilesTable)
74	    .where(eq(userProfilesTable.userId, coach.userId));
75	  if (profile?.status !== "active") {
76	    return { ok: false, error: "Coach Stripe account not active" };
77	  }
78	
79	  if (coach.travelPolicy === "affiliated_only") {
80	    const [aff] = await db
81	      .select({ id: courtCoachesTable.id })
82	      .from(courtCoachesTable)
83	      .where(and(
84	        eq(courtCoachesTable.coachId, coach.id),
85	        eq(courtCoachesTable.courtId, args.courtId),
86	      ));
87	    if (!aff) return { ok: false, error: "Coach not affiliated with this court" };
88	  }
89	
90	  // Continuous coverage over the booking window. This catches the race where
91	  // a coach blocks a slot between the picker query and the checkout call.
92	  const winStart = vilniusToUtc(args.date, args.startTime).getTime();
93	  const winEnd = vilniusToUtc(args.date, args.endTime).getTime();
94	  if (winEnd <= winStart || (winEnd - winStart) % SLOT_MS !== 0) {
95	    return { ok: false, error: "Invalid booking window" };
96	  }
97	  const slots = await getCoachAvailability(coach.id, args.date);
98	  const slotStarts = new Set(slots.map((s) => new Date(s.start).getTime()));
99	  for (let t = winStart; t < winEnd; t += SLOT_MS) {
100	    if (!slotStarts.has(t)) return { ok: false, error: "Coach unavailable for window" };
101	  }
102	
103	  const minutes = (winEnd - winStart) / 60_000;
104	  const coachCents = Math.round((coach.pricePerHour * minutes) / 60);
105	  return { ok: true, coachUserId: coach.userId, coachCents };
106	}
107	
108	const router: IRouter = Router();
109	
110	// ─── Publishable key (safe for frontend) ─────────────────────────────────────
111	router.get("/payments/config", async (_req, res) => {
112	  try {
113	    const publishableKey = await getStripePublishableKey();
114	    res.json({ publishableKey });
115	  } catch (err) {
116	    logger.error({ err }, "Failed to get Stripe publishable key");
117	    res.status(500).json({ error: "Stripe not configured" });
118	  }
119	});
120	
121	// ─── Create Checkout Session (player or guest booking) ───────────────────────
122	// No requireAuth: a guest booking has no Clerk session, so we authorize via the
123	// `managementToken` (returned to the client when the booking was created).
124	// Authenticated callers are still authorized via session as before.
125	router.post("/payments/create-checkout", async (req, res): Promise<void> => {
126	  const parsed = CreateCheckoutSessionBody.safeParse(req.body);
127	  if (!parsed.success) {
128	    res.status(400).json({ error: parsed.error.message });
129	    return;
130	  }
131	
132	  const { bookingId, successUrl, cancelUrl } = parsed.data;
133	  // Guest checkout passes the management token in the body (CreateCheckoutSessionBody
134	  // doesn't list it, so read it raw — we never trust it without comparing to DB).
135	  const providedToken =
136	    typeof (req.body as any)?.managementToken === "string"
137	      ? ((req.body as any).managementToken as string)
138	      : null;
139	
140	  const rows = await db
141	    .select({ booking: bookingsTable, court: courtsTable, facility: facilitiesTable })
142	    .from(bookingsTable)
143	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
144	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
145	    .where(eq(bookingsTable.id, bookingId));
146	
147	  if (!rows[0]) {
148	    res.status(404).json({ error: "Booking not found" });
149	    return;
150	  }
151	
152	  const { booking, court, facility } = rows[0];
153	
154	  // Authorization:
155	  // 1) Authenticated booker / court owner / admin (existing behavior), OR
156	  // 2) Guest path: booking.bookerUserId is null AND request supplied the matching managementToken.
157	  const callerId = getCurrentUserId(req);
158	  let authorized = false;
159	  if (callerId) {
160	    const isBooker = booking.bookerUserId === callerId;
161	    const isCourtOwner = facility?.ownerUserId === callerId;
162	    const callerRole = await getUserRole(callerId);
163	    authorized = isBooker || isCourtOwner || callerRole === "admin";
164	  }
165	  if (!authorized && booking.bookerUserId === null && timingSafeEqualToken(providedToken, booking.managementToken)) {
166	    authorized = true;
167	  }
168	  if (!authorized) {
169	    res.status(403).json({ error: "Forbidden" });
170	    return;
171	  }
172	
173	  const linkGameIdRaw = (req.body as any).linkGameId;
174	  const linkGameId: number | null = Number.isInteger(linkGameIdRaw) && linkGameIdRaw > 0 ? linkGameIdRaw : null;
175	
176	  let stripe: any;
177	  try {
178	    stripe = await getUncachableStripeClient();
179	  } catch (err) {
180	    logger.warn("Stripe not configured — using mock checkout");
181	    const mockSessionId = `mock_session_${bookingId}_${Date.now()}`;
182	    await db
183	      .update(bookingsTable)
184	      .set({ stripeSessionId: mockSessionId, status: "confirmed" })
185	      .where(eq(bookingsTable.id, bookingId));
186	    await db
187	      .update(courtsTable)
188	      .set({ totalBookings: sql`total_bookings + 1` })
189	      .where(eq(courtsTable.id, booking.courtId));
190	    if (linkGameId && booking.bookerUserId) {
191	      const [game] = await db.select({ creatorUserId: gamesTable.creatorUserId })
192	        .from(gamesTable).where(eq(gamesTable.id, linkGameId));
193	      if (game && game.creatorUserId === booking.bookerUserId) {
194	        const toMin = (t: string) => { const [h, m] = t.split(":").map(Number); return h * 60 + m; };
195	        await db.update(gamesTable)
196	          .set({
197	            bookingId: booking.id,
198	            courtId: booking.courtId,
199	            facilityId: facility?.id ?? null,
200	            placeName: court?.name ?? null,
201	            city: facility?.city ?? "",
202	            datetime: `${booking.date}T${booking.startTime}:00`,
203	            durationMinutes: toMin(booking.endTime) - toMin(booking.startTime),
204	          })
205	          .where(eq(gamesTable.id, linkGameId));
206	      }
207	    }
208	    const mockSuccessUrl = `${successUrl}${successUrl.includes("?") ? "&" : "?"}session_id=${mockSessionId}`;
209	    res.json(CreateCheckoutSessionResponse.parse({ sessionId: mockSessionId, url: mockSuccessUrl }));
210	    return;
211	  }
212	
213	  // Two ways a booking can carry coach attachment:
214	  //  (a) Coach-service path — booking was created by POST /coach-bookings
215	  //      with coachServiceId/coachId/coachAmountCents/totalPrice already
216	  //      snapshotted (Invariant B). We MUST use those values verbatim;
217	  //      re-deriving from coach.pricePerHour would drift if the coach
218	  //      edited their service catalog after the booking was created.
219	  //  (b) Legacy court+coach picker — frontend sends `coachId` in the body
220	  //      and we re-authorize + price via authorizeAndPriceCoach. Path used
221	  //      by the existing court booking page.
222	  let courtCents: number;
223	  let coachCents = 0;
224	  let coachUserId: string | null = null;
225	  let coachId: number | null = null;
226	  let writeCoachOnBooking = false;
227	
228	  if (booking.coachServiceId != null && booking.coachId != null && booking.coachAmountCents != null) {
229	    const storedTotalCents = Math.round(Number(booking.totalPrice) * 100);
230	    coachCents = booking.coachAmountCents;
231	    coachUserId = booking.coachId;
232	    courtCents = storedTotalCents - coachCents;
233	    if (courtCents < 0) {
234	      res.status(422).json({ error: "Invalid booking totals" });
235	      return;
236	    }
237	  } else {
238	    courtCents = Math.round(Number(booking.totalPrice) * 100);
239	    const coachIdRaw = (req.body as any).coachId;
240	    coachId = Number.isInteger(coachIdRaw) && coachIdRaw > 0 ? coachIdRaw : null;
241	    if (coachId !== null) {
242	      const auth = await authorizeAndPriceCoach({
243	        coachId,
244	        courtId: booking.courtId,
245	        date: booking.date,
246	        startTime: booking.startTime,
247	        endTime: booking.endTime,
248	      });
249	      if (!auth.ok) {
250	        res.status(422).json({ error: auth.error });
251	        return;
252	      }
253	      coachCents = auth.coachCents;
254	      coachUserId = auth.coachUserId;
255	      writeCoachOnBooking = true;
256	    }
257	  }
258	
259	  const totalCents = courtCents + coachCents;
260	  const hasCoachAttachment = coachUserId !== null;
261	
262	  // Resolve payout destination: use the court owner's Connect account.
263	  let connectAccountId: string | null = null;
264	  if (facility?.ownerUserId) {
265	    const [profile] = await db
266	      .select({ stripeAccountId: userProfilesTable.stripeAccountId, status: userProfilesTable.stripeAccountStatus })
267	      .from(userProfilesTable)
268	      .where(eq(userProfilesTable.userId, facility.ownerUserId));
269	    if (profile?.stripeAccountId && profile.status === "active") {
270	      connectAccountId = profile.stripeAccountId;
271	    }
272	  }
273	
274	  // With a coach attached we MUST be able to destination-charge the owner
275	  // — otherwise platform balance holds both the coach and court portions
276	  // and the booking strands the owner's share until manual reconciliation.
277	  if (hasCoachAttachment && !connectAccountId) {
278	    res.status(422).json({ error: "Court owner Stripe account not active" });
279	    return;
280	  }
281	
282	  const sessionParams: any = {
283	    payment_method_types: ["card"],
284	    line_items: [
285	      {
286	        price_data: {
287	          currency: "eur",
288	          product_data: {
289	            name: `${court?.name ?? "Kortas"} – rezervacija${hasCoachAttachment ? " + treneris" : ""}`,
290	            description: `${booking.date} · ${booking.startTime}–${booking.endTime}`,
291	          },
292	          unit_amount: totalCents,
293	        },
294	        quantity: 1,
295	      },
296	    ],
297	    mode: "payment",
298	    success_url: `${successUrl}${successUrl.includes("?") ? "&" : "?"}session_id={CHECKOUT_SESSION_ID}`,
299	    cancel_url: cancelUrl,
300	    metadata: {
301	      bookingId: String(bookingId),
302	      ...(linkGameId ? { linkGameId: String(linkGameId) } : {}),
303	      ...(hasCoachAttachment
304	        ? {
305	            coachAmountCents: String(coachCents),
306	            ...(coachId !== null ? { coachId: String(coachId) } : {}),
307	            ...(coachUserId ? { coachUserId } : {}),
308	          }
309	        : {}),
310	    },
311	    customer_email: booking.customerEmail,
312	    locale: "lt",
313	  };
314	
315	  if (connectAccountId) {
316	    const platformFeeCourt = Math.round((courtCents * COURT_PLATFORM_FEE_PCT) / 100);
317	    if (hasCoachAttachment) {
318	      // Coach split: route only the court owner's net share via transfer_data;
319	      // the coach's portion stays on the platform balance for a separate
320	      // transfers.create call after payment confirmation. application_fee is
321	      // omitted because it's ignored when transfer_data.amount is set.
322	      sessionParams.payment_intent_data = {
323	        transfer_data: {
324	          destination: connectAccountId,
325	          amount: courtCents - platformFeeCourt,
326	        },
327	      };
328	    } else {
329	      // Single-payer (existing behavior): 5% platform fee on the total.
330	      sessionParams.payment_intent_data = {
331	        application_fee_amount: platformFeeCourt,
332	        transfer_data: { destination: connectAccountId },
333	      };
334	    }
335	  }
336	
337	  const session = await stripe.checkout.sessions.create(sessionParams);
338	
339	  // Persist coach attachment + updated total on the booking. Done after the
340	  // Stripe call so we don't write coach data for a booking whose checkout
341	  // session never materialized. Skipped for the coach-service path — those
342	  // bookings already have coachId/coachAmountCents/totalPrice snapshotted at
343	  // creation time (Invariant B). Overwriting them here would silently break
344	  // historical immutability.
345	  await db
346	    .update(bookingsTable)
347	    .set({
348	      stripeSessionId: session.id,
349	      ...(writeCoachOnBooking
350	        ? {
351	            coachId: coachUserId,
352	            coachAmountCents: coachCents,
353	            totalPrice: (totalCents / 100).toFixed(2),
354	          }
355	        : {}),
356	    })
357	    .where(eq(bookingsTable.id, bookingId));
358	
359	  res.json(CreateCheckoutSessionResponse.parse({ sessionId: session.id, url: session.url! }));
360	});
361	
362	// ─── Confirm payment after redirect ──────────────────────────────────────────
363	router.post("/payments/confirm", async (req, res): Promise<void> => {
364	  const parsed = ConfirmPaymentBody.safeParse(req.body);
365	  if (!parsed.success) {
366	    res.status(400).json({ error: parsed.error.message });
367	    return;
368	  }
369	
370	  const { sessionId } = parsed.data;
371	
372	  const rows = await db
373	    .select({
374	      booking: bookingsTable,
375	      courtName: courtsTable.name,
376	      courtId: courtsTable.id,
377	      courtAddress: facilitiesTable.address,
378	      courtCity: facilitiesTable.city,
379	      courtPhone: courtsTable.phone,
380	      courtImageUrl: courtsTable.imageUrl,
381	      ownerName: facilitiesTable.name,
382	      ownerEmail: facilitiesTable.email,
383	      facilityId: facilitiesTable.id,
384	      instantBookingEnabled: courtsTable.instantBookingEnabled,
385	    })
386	    .from(bookingsTable)
387	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
388	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
389	    .where(eq(bookingsTable.stripeSessionId, sessionId));
390	
391	  if (!rows[0]) {
392	    res.status(404).json({ error: "Booking not found for session" });
393	    return;
394	  }
395	
396	  // Authorization: for authenticated-user bookings, the caller must be the booker.
397	  // Guest bookings (bookerUserId = null) are authorized by possession of the session ID.
398	  const confirmCallerId = getCurrentUserId(req);
399	  if (rows[0].booking.bookerUserId !== null && confirmCallerId !== rows[0].booking.bookerUserId) {
400	    res.status(403).json({ error: "Forbidden" });
401	    return;
402	  }
403	
404	  let linkGameId: number | null = null;
405	  let stripePaymentIntentId: string | null = null;
406	  // Keep a reference to the Stripe client when configured so we can fire the
407	  // coach transfer below without re-loading it.
408	  let stripeClient: any = null;
409	  if (!sessionId.startsWith("mock_")) {
410	    try {
411	      stripeClient = await getUncachableStripeClient();
412	      const session = await stripeClient.checkout.sessions.retrieve(sessionId);
413	      if (session.payment_status !== "paid") {
414	        res.status(402).json({ error: "Payment not completed" });
415	        return;
416	      }
417	      stripePaymentIntentId =
418	        typeof session.payment_intent === "string"
419	          ? session.payment_intent
420	          : session.payment_intent?.id ?? null;
421	      const lgId = session.metadata?.linkGameId;
422	      if (lgId) linkGameId = parseInt(lgId, 10);
423	    } catch (err) {
424	      logger.error({ err }, "Stripe retrieve session error");
425	    }
426	  }
427	
428	  const newStatus = "confirmed";
429	
430	  // Idempotent transition: only the first caller (race between Stripe webhook and
431	  // the eager success-page POST) actually flips status and runs side effects.
432	  // Subsequent calls return the already-confirmed booking without re-incrementing
433	  // counters or re-sending emails.
434	  const updated = await db
435	    .update(bookingsTable)
436	    .set({
437	      status: newStatus,
438	      ...(stripePaymentIntentId ? { stripePaymentIntentId } : {}),
439	    })
440	    .where(and(
441	      eq(bookingsTable.stripeSessionId, sessionId),
442	      ne(bookingsTable.status, "confirmed"),
443	    ))
444	    .returning();
445	
446	  if (updated.length === 0) {
447	    // Already confirmed by webhook (or another concurrent call). Return current state.
448	    res.json(ConfirmPaymentResponse.parse({
449	      ...rows[0].booking,
450	      totalPrice: Number(rows[0].booking.totalPrice),
451	      refundAmount: Number(rows[0].booking.refundAmount ?? 0),
452	      pricePerSlot: rows[0].booking.pricePerSlot != null ? Number(rows[0].booking.pricePerSlot) : undefined,
453	      totalSlots: rows[0].booking.totalSlots ?? undefined,
454	      splitInviteToken: rows[0].booking.splitInviteToken ?? undefined,
455	      stripeSessionId: rows[0].booking.stripeSessionId ?? undefined,
456	      stripeRefundId: rows[0].booking.stripeRefundId ?? undefined,
457	      rentedItems: rows[0].booking.rentedItems ?? undefined,
458	      courtName: rows[0].courtName ?? undefined,
459	      status: "confirmed",
460	      managementToken: undefined,
461	    }));
462	    return;
463	  }
464	
465	  const booking = updated[0];
466	
467	  // Issue the coach's share via a separate Stripe transfer. Idempotent and
468	  // safe to race with the webhook handler — only the first caller mutates
469	  // the booking row.
470	  if (stripeClient && booking.coachId) {
471	    await maybeIssueCoachTransfer(booking, stripeClient);
472	  }
473	
474	  if (linkGameId && booking.bookerUserId) {
475	    const [game] = await db.select({ creatorUserId: gamesTable.creatorUserId })
476	      .from(gamesTable).where(eq(gamesTable.id, linkGameId));
477	    if (game && game.creatorUserId === booking.bookerUserId) {
478	      const toMin = (t: string) => { const [h, m] = t.split(":").map(Number); return h * 60 + m; };
479	      await db.update(gamesTable)
480	        .set({
481	          bookingId: booking.id,
482	          courtId: booking.courtId,
483	          facilityId: rows[0].facilityId ?? null,
484	          placeName: rows[0].courtName ?? null,
485	          city: rows[0].courtCity ?? "",
486	          datetime: `${booking.date}T${booking.startTime}:00`,
487	          durationMinutes: toMin(booking.endTime) - toMin(booking.startTime),
488	        })
489	        .where(eq(gamesTable.id, linkGameId));
490	    }
491	  }
492	
493	  await db
494	    .update(courtsTable)
495	    .set({ totalBookings: sql`total_bookings + 1` })
496	    .where(eq(courtsTable.id, rows[0].booking.courtId));
497	
498	  sendBookingConfirmationEmail({
499	    customerName: booking.customerName,
500	    customerEmail: booking.customerEmail,
501	    courtName: rows[0].courtName ?? "Kortas",
502	    courtId: rows[0].courtId ?? 0,
503	    courtAddress: rows[0].courtAddress ?? "",
504	    courtCity: rows[0].courtCity ?? "",
505	    courtPhone: rows[0].courtPhone ?? undefined,
506	    courtImageUrl: rows[0].courtImageUrl ?? undefined,
507	    date: booking.date,
508	    startTime: booking.startTime,
509	    endTime: booking.endTime,
