    // back-compat with older wizards that submitted only `sports: string[]`.
    const sportsAudiencesRaw = Array.isArray(requestData.sportsAudiences)
      ? (requestData.sportsAudiences as Array<{ sport?: unknown; audiences?: unknown }>)
      : [];
