      .filter((e) => typeof e?.sport === "string" && (e.sport as string).trim().length > 0)
      .map((e) => ({
        sport: String(e.sport).trim(),
        audiences: Array.isArray(e.audiences)
          ? (e.audiences as unknown[]).map(String).filter(Boolean)
          : [],
      }));

    const sportsArr: string[] = sportsAudiences.length > 0
      ? sportsAudiences.map((e) => e.sport)
      : Array.isArray(requestData.sports)
        ? (requestData.sports as unknown[]).map(String)
        : [];

    // pricePerHour stored as integer cents — coerce from request payload.
    const rawPrice = requestData.pricePerHour;
    const pricePerHour =
      typeof rawPrice === "number" && Number.isFinite(rawPrice) && rawPrice >= 0
        ? Math.round(rawPrice)
        : typeof rawPrice === "string" && rawPrice.trim() !== "" && Number.isFinite(Number(rawPrice))
        ? Math.round(Number(rawPrice))
        : null;

    const travelPolicy =
      requestData.travelPolicy === "any_court" || requestData.travelPolicy === "affiliated_only"
        ? (requestData.travelPolicy as string)
        : undefined;
    const cancellationPolicy =
      requestData.cancellationPolicy === "flexible" ||
      requestData.cancellationPolicy === "standard" ||
      requestData.cancellationPolicy === "strict"
        ? (requestData.cancellationPolicy as string)
        : undefined;

    const [inserted] = await db
      .insert(coachesTable)
      .values({
        userId,
        name: (requestData.name as string | undefined) ?? "Coach",
        email: (requestData.email as string | undefined) ?? "",
        bio: (requestData.bio as string | undefined) ?? null,
        photoUrl: (requestData.photoUrl as string | undefined) ?? null,
        pricePerHour,
        sports: sportsArr,
        availabilityDescription: (requestData.availabilityDescription as string | undefined) ?? null,
        phone: (requestData.phone as string | undefined) ?? null,
        ...(travelPolicy && { travelPolicy }),
        ...(cancellationPolicy && { cancellationPolicy }),
      })
      .onConflictDoUpdate({
        target: coachesTable.userId,
        set: {
          bio: (requestData.bio as string | undefined) ?? null,
          photoUrl: (requestData.photoUrl as string | undefined) ?? null,
          sports: sportsArr,
          pricePerHour,
          availabilityDescription: (requestData.availabilityDescription as string | undefined) ?? null,
          phone: (requestData.phone as string | undefined) ?? null,
          ...(travelPolicy && { travelPolicy }),
          ...(cancellationPolicy && { cancellationPolicy }),
        },
      })
      .returning();

    if (inserted && sportsAudiences.length > 0) {
      // Replace-all sync of the per-sport audience junction. Wrapped in a
      // transaction so the table is never left half-populated on error.
